<?php $loggedIn=\App\Core\Auth::user() && \App\Core\Auth::user()['role']==='student'; $return='/cbt/test/'.(int)$test['id'].'?enroll=1'; ?>
<section class="page narrow student-page"><div class="card enroll-detail"><?php if(!empty($test['thumbnail_path'])):?><img class="detail-thumbnail" src="/cbt/media/<?=e($test['thumbnail_path'])?>" alt="<?=e($test['title'])?> thumbnail"><?php endif;?><span class="subject"><?=e($test['subject'])?></span><h1><?=e($test['title'])?></h1><p><?=e($test['exam_name'])?> · <?=e($test['category'])?></p><div class="detail-table"><div><span>Full marks</span><b><?=e($test['full_marks'])?></b></div><div><span>Total questions</span><b><?=e($test['total_questions'])?></b></div><div><span>Duration</span><b><?=e($test['duration_minutes'])?> minutes</b></div><div><span>Start date &amp; time</span><b><?=e(date('d M Y, h:i A',strtotime($test['starts_at'])))?></b></div><div><span>End date &amp; time</span><b><?=e(date('d M Y, h:i A',strtotime($test['ends_at'])))?></b></div><div><span>Enrollment fee</span><b><?=((float)$test['fee']>0)?'₹'.e($test['fee']):'Free'?></b></div></div><div class="warning"><b>Important note:</b> Login is required only to enroll and pay. You must start the exam before the examination window closes.</div><?php if($loggedIn):?><form method="post" action="/cbt/api/cbt/tests/<?=e($test['id'])?>/enroll" data-enrollment-form data-auto-enroll><?=csrf_field()?><button class="btn wide"><?=((float)$test['fee']>0)?'Continue to payment':'Enroll now'?></button></form><?php else:?><a class="btn wide" href="/cbt/login?return=<?=e(rawurlencode($return))?>"><?=((float)$test['fee']>0)?'Login to pay & enroll':'Login to enroll'?></a><?php endif;?><a class="public-back-link" href="/cbt/catalogue">← Back to all exams</a></div></section>
